            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "In order to get what we've got, Anita, we have, in effect, traded these people out of what was the most important thing on earth to them — the feeling of being needed and useful, the foundation of self-respect.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Bad guys turned informer. Good guys didn't — no matter when, no matter what.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "And a step backward, after making a wrong turn, is a step in the right direction.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Every passing hour brings the Solar System forty-three thousand miles closer to Globular Cluster M13 in Hercules—and still there are some misfits who insist that there is no such thing as progress.", Author = "Kurt Vonnegut" },
