            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The big trouble with dumb bastards is that they are too dumb to believe there is such a thing as being smart.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "There is no reason why good cannot triumph as often as evil. The triumph of anything is a matter of organization.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "O Lord Most High, what a glorious weapon is Thy Apathy, for we have unsheathed it, have thrust and slashed mightily with it, and the claptrap that has so often enslaved us or driven us into the madhouse lies slain!", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I can think of no more stirring symbol of man's humanity to man than a fire engine.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I was a victim of a series of accidents, as are we all.", Author = "Kurt Vonnegut" },
