            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The controls were anything but a hunch-player's delight in a Universe composed of one-trillionth part matter to one decillion parts black velvet futility.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The thing I just wrote is my masterpiece. The rest of it is going to be crap from now on.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "If you are going to be a writer, you must be paranoid. The thing is, in the arts if you don't overreact, you fall asleep.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Science fiction is like other writing. It is just novels and short stories with machines.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Be kind. Don't kill for any reason. Don't even kill out of self-defense. Really — I mean that. Don't take any more than you need of anything. Help others.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Humor is a way of coping with real trouble. My next book is a comedy. It is about the largest massacre in the history of Europe.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I sometimes wondered what the use of any of the arts was. The best thing I could come up with was what I call the canary in the coal mine theory of the arts.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "High school is closer to the core of the American experience than anything else I can think of.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I simply never unlearned junior civics. I still believe in it.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Give me knowledge or give me death!", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "What should young people do with their lives today? Many things, obviously. But the most daring thing is to create stable communities in which the terrible disease of loneliness can be cured.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "It can make quite a difference not just to you but to humanity: the sort of boss you choose, whose dreams you help come true.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Well, I've worried some about, you know, why write books… why are we teaching people to write books when presidents and senators do not read them, and generals do not read them.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I was taught that the human brain was the crowning glory of evolution so far, but I think it's a very poor scheme for survival.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Find a subject you care about.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Pity the readers.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Literature is idiosyncratic arrangements in horizontal lines in only twenty-six symbols, ten arabic numbers, and about eight punctuation marks.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "You learn about life by the accidents you have, over and over again.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "One of the great American tragedies is to have participated in a just war.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I urge you to please notice when you are happy, and exclaim or murmur or think at some point, 'If this isn't nice, I don't know what is.'", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "When it became obvious what a dumb and cruel and spiritually and financially and militarily ruinous mistake our war in Vietnam was, every artist worth a damn in this country came out against the thing.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "We're terrible animals. I think that the Earth's immune system is trying to get rid of us, as well it should.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I have wanted to give Iraq a lesson in democracy — because we're experienced with it, you know.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I do feel that evolution is being controlled by some sort of divine engineer. I can't help thinking that.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The moral of the story is, is we're here on Earth to fart around.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Where is home? I've wondered where home is, and I realized, it's not Mars or someplace like that, it's Indianapolis when I was nine years old.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "No matter how corrupt, greedy, and heartless our government, our corporations, our media, and our religious and charitable institutions may become, the music will still be wonderful.", Author = "Kurt Vonnegut" },
