            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "My theory is that all women have hydrofluoric acid bottled up inside.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Democracy owed its life to know-how.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Anita had the mechanics of marriage down pat, even to the subtlest conventions.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "It was an appalling thought, to be so well-integrated into the machinery of society and history as to be able to move in only one plane, and along one line.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I want to stay as close to the edge as I can without going over. Out on the edge you see all kinds of things you can't see from the center.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Washington is worse, Paul—Ilium to the tenth power. Stupid, arrogant, self-congratulatory, unimaginative, humorless men.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "You know, in a way I wish I hadn't met you two. It's much more convenient to think of the opposition as a nice homogeneous, dead-wrong mass.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "These displaced people need something, and the clergy can't give it to them—or it's impossible for them to take what the clergy offers.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Everybody's shaking in his boots, so don't be bluffed.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "And as Paul said these things to himself, a wave of sadness washed over them as though they'd been written in sand.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Why are you quitting? Sick of my job.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Because it was pointless.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Things don't stay the way they are. It's too entertaining to try to change them.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "If only it weren't for the people, the goddamned people, always getting tangled up in the machinery.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Mankind, ignorant of the truths that lie withing every human being, looked outward—pushed ever outward.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "These unhappy agents found what had already been found in abundance on Earth—a nightmare of meaningless without end.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "He ransacked his memory like a thief going through another man's billfold.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I tell you, Mr. Constant, it's a thankless job, telling people it's a hard, hard Universe they're in.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The insane, on occasion, are not without their charms.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The riot, then, was an exercise in science and theology—a seeking after clues by the living as to what life was all about.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "You're a member of it, you know.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Rumfoord had known that Constant would try to debase the picture by using it in commerce.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Life for a punctual person is like a roller coaster.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Son—they say there isn't any royalty in this country, but do you want me to tell you how to be king of the United States of America?", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "When you get right down to it, everybody's having a perfectly lousy time of it, and I mean everybody.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "There is a riddle about a man who is locked in a room with nothing but a bed and a calendar, and the question is: How does he survive?", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "It was a marvelous engine for doing violence to the spirit of thousands of laws without actually running afoul of so much as a city ordinance.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "All the things you are are going to be sued and sued successfully.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "He was too good a soldier to go around asking questions, trying to round out his knowledge.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Any man who would change the World in a significant way must have showmanship, a genial willingness to shed other people's blood, and a plausible new religion to introduce during the brief period of repentance and horror that usually follows bloodshed.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The name of the new religion is The Church of God the Utterly Indifferent.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The two chief teachings of this religion are these: Puny man can do nothing at all to help or please God Almighty, and Luck is not the hand of God.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "During my next visit with you, fellow-believers, I shall tell you a parable about people who do things that they think God Almighty wants done.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "There was not a country in the world that had not fought a battle in the war of all Earth against the invaders from Mars.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "All was forgiven. All living things were brothers, and all dead things were even more so.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "He didn't go to any trouble to get you here safe and sound, any more than He would go to the trouble to kill you.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "His poor soul was flooded with pleasure as he realized that one friend was all that a man needed in order to be well-supplied with friendship.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "It may surprise you to learn that I take a certain pride, no matter how foolishly mistaken that pride may be, in making my own decisions for my own reasons.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "As far as I'm concerned, the Universe is a junk yard, with everything in it overpriced.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "It was in the nature of truly effective good-luck pieces that human beings never really owned them.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "You finally fell in love, I see.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I would say, 'Is there anything I can do?'—but Skip once told me that that was the most hateful and stupid expression in the English language.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "You finally fell in love, I see.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "A purpose of human life, no matter who is controlling it, is to love whoever is around to be loved.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "We few, we happy few, we band of brothers — joined in the serious business of keeping our food, shelter, clothing and loved ones from combining with oxygen.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "The other processes try it for a while, note that the conscience is unappeased, that it continues to shriek, and they note, too, that the outside world has not been even microscopically improved by the unselfish acts the conscience has demanded.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Enlightened Self-interest gives them a flag, which they adore on sight.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Hello, babies. Welcome to Earth. It's hot in the summer and cold in the winter.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "We don't piss in your ashtrays, So please don't throw cigarettes in our urinals.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "If I'd been born in Germany, I suppose I would have been a Nazi, bopping Jews and gypsies and Poles around.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "When you're dead you're dead.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "All people are insane. They will do anything at any time, and God help anybody who looks for reasons.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Where's evil? It's that large part of every man that wants to hate without limit, that wants to hate with God on its side.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "You hate America, don't you?", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "That would be as silly as loving it.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Drawn crudely in the dust of three window-panes were a swastika, a hammer and sickle, and the Stars and Stripes.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "I had drawn the three symbols weeks before, at the conclusion of an argument about patriotism with Kraft.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "What froze me was the fact that I had absolutely no reason to move in any direction.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Generally speaking, espionage offers each spy an opportunity to go crazy in a way he finds irresistible.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "If you find your life tangled up with somebody else's life for no very logical reasons, that person may be a member of your karass.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Man created the checkerboard; God created the karass.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Someday, someday, this crazy world will have to end, And our God will take things back that He to us did lend.", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Peculiar Travel Suggestions are Dancing Lessons From God", Author = "Kurt Vonnegut" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Kurt_Vonnegut", Text = "Tiger got to sleep, bird got to land; Man got to tell himself he understand.", Author = "Kurt Vonnegut" },
        };
    }
